1	package components
2	
3	import (
4		"strings"
5		"testing"
6	
7		"charm.land/lipgloss/v2"
8		"github.com/charmbracelet/x/ansi"
9		"github.com/mattn/go-runewidth"
10	
11		"github.com/anthnel/devdesk/internal/ui/indicator"
12		"github.com/anthnel/devdesk/internal/ui/theme"
13	)
14	
15	// ── The activity dot (DEVDESK-341) ───────────────────────────────────────────
16	
17	// runningDot is the dot the footer must emit for a blink phase: the shared
18	// Running glyph, in its indicator colour, on the app background (Rule 115).
19	func runningDot(on bool) string {
20		return indicator.Style(indicator.Running).
21			Background(theme.ColorBackground).
22			Render(indicator.Glyph(indicator.Running, on))
23	}
24	
25	func hasBrailleRune(s string) bool {
26		for _, r := range s {
27			if r >= 0x2800 && r <= 0x28FF {
28				return true
29			}
30		}
31		return false
32	}
33	
34	// 1, 2: the dot is steady without a phase call, and follows SetBlinkPhase.
35	func TestActivityDotFollowsTheBlinkPhase(t *testing.T) {
36		st := Status{Text: "1 job running", Activity: true}
37		cases := []struct {
38			name string
39			set  func(f *FooterMessage)
40			want string
41		}{
42			{"no call is steady on", func(*FooterMessage) {}, "● 1 job running"},
43			{"phase on", func(f *FooterMessage) { f.SetBlinkPhase(true) }, "● 1 job running"},
44			{"phase off", func(f *FooterMessage) { f.SetBlinkPhase(false) }, "○ 1 job running"},
45		}
46		for _, c := range cases {
47			t.Run(c.name, func(t *testing.T) {
48				var f FooterMessage
49				c.set(&f)
50				got := ansi.Strip(f.View(60, st))
51				if !strings.Contains(got, c.want) {
52					t.Errorf("footer line = %q, want it to contain %q", got, c.want)
53				}
54			})
55		}
56	}
57	
58	// 3: colour and background come from indicator.Style, never from the spinner style.
59	func TestActivityDotIsStyledAsTheRunningIndicator(t *testing.T) {
60		for _, on := range []bool{true, false} {
61			var f FooterMessage
62			f.SetBlinkPhase(on)
63			f.SetSpinnerFrame(theme.SpinnerStyle().Render("⠹"))
64			got := f.View(60, Status{Text: "work", Activity: true})
65			if want := runningDot(on); !strings.Contains(got, want) {
66				t.Errorf("on=%v: the dot is not rendered as indicator.Style(Running) on the app background\n got: %q\nwant it to contain: %q",
67					on, got, want)
68			}
69		}
70	}
71	
72	// 4: swapping ● for ○ moves nothing.
73	func TestActivityDotPhaseDoesNotShiftTheText(t *testing.T) {
74		st := Status{Text: "Syncing 3/12", Activity: true}
75		var on, off FooterMessage
76		on.SetBlinkPhase(true)
77		off.SetBlinkPhase(false)
78		a, b := on.View(60, st), off.View(60, st)
79		if wa, wb := lipgloss.Width(a), lipgloss.Width(b); wa != wb {
80			t.Errorf("width differs between phases: %d vs %d", wa, wb)
81		}
82		if ia, ib := strings.Index(ansi.Strip(a), "Syncing"), strings.Index(ansi.Strip(b), "Syncing"); ia < 0 || ia != ib {
83			t.Errorf("text column differs between phases: %d vs %d", ia, ib)
84		}
85	}
86	
87	// 5, 6: a detail with a glyph already carries the dot; one without does not.
88	func TestActivityDotAndRowDetail(t *testing.T) {
89		var f FooterMessage
90		withGlyph := ansi.Strip(f.View(80, Status{
91			Activity: true, Detail: RowDetail{Glyph: "●", Lead: "Scanning ", Target: "x"},
92		}))
93		if n := strings.Count(withGlyph, "●"); n != 1 {
94			t.Errorf("a glyph detail must leave exactly one ●, got %d in %q", n, withGlyph)
95		}
96	
97		noGlyph := ansi.Strip(f.View(80, Status{
98			Activity: true, Detail: RowDetail{Lead: "Scanning ", Target: "x"},
99		}))
100		if !strings.Contains(noGlyph, "● Scanning") {
101			t.Errorf("a detail without a glyph must keep the dot, got %q", noGlyph)
102		}
103	}
104	
105	// 7: no Activity, no dot, whatever the phase.
106	func TestNoActivityMeansNoDot(t *testing.T) {
107		for _, on := range []bool{true, false} {
108			var f FooterMessage
109			f.SetBlinkPhase(on)
110			got := ansi.Strip(f.View(60, Status{Text: "plain status"}))
111			if strings.ContainsAny(got, "●○") {
112				t.Errorf("on=%v: a status without Activity shows a dot: %q", on, got)
113			}
114		}
115	}
116	
117	// 8: error > warning > info > status; a timed message hides the dot.
118	func TestTimedMessageHidesTheActivityDot(t *testing.T) {
119		for name, set := range map[string]func(*FooterMessage, string){
120			"info":  func(f *FooterMessage, s string) { f.Info(s) },
121			"warn":  func(f *FooterMessage, s string) { f.Warn(s) },
122			"error": func(f *FooterMessage, s string) { f.Error(s) },
123		} {
124			t.Run(name, func(t *testing.T) {
125				var f FooterMessage
126				set(&f, "the message")
127				got := ansi.Strip(f.View(60, Status{Text: "1 job running", Activity: true}))
128				if !strings.Contains(got, "the message") {
129					t.Errorf("message not shown: %q", got)
130				}
131				if strings.ContainsAny(got, "●○") || strings.Contains(got, "1 job running") {
132					t.Errorf("status leaked through a %s message: %q", name, got)
133				}
134			})
135		}
136	}
137	
138	// 9: Activity wins over Spinner.
139	func TestActivityWinsOverSpinner(t *testing.T) {
140		var f FooterMessage
141		f.SetSpinnerFrame("⠹")
142		got := f.View(60, Status{Text: "work", Activity: true, Spinner: true})
